const TAU=Math.PI*2;
function stars(b,m,radius,y,count=96){for(let i=0;i<count;i++){const a=i*2.399,r=Math.sqrt((i+.5)/count)*radius;b.oval(i%4?m.coolLamp:m.lamp,Math.cos(a)*r,y+Math.sin(i*1.71)*.06,Math.sin(a)*r,.035,.02,.035);}}
